    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores;

    /**
     * Customer AWS account ID used for role trust.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty()
    public accountId: string;

    /**
     * AWS region for ingestion. Default is us-east-1.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public region?: string;

    /**
     * IAM role ARN provisioned for customer uploads.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * External ID required to assume the provisioned role.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * S3 ingestion prefix for this business.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * S3 DLQ prefix for this business.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: Partial<DatastoreAccessInformation>) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.platform = platform ? platform : SupportedDatastores.s3;
            this.accountId = accountId;
            this.region = region ? region : process.env.AWS_REGION || 'us-east-1';
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
            this.businessID = businessID;
            this.measurementId = measurementId;
        }
    }

    public static roleName(businessID: string, measurementId: string) {
        return `datastore-${businessID}-${measurementId}`;
    }

    public static trustPolicyDocument(accountId: string, externalId: string) {
        return JSON.stringify({
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        });
    }

    public static permissionsPolicyDocument(businessID: string) {
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        return JSON.stringify({
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [
                        `arn:aws:s3:::${ingestionBucket}/${businessID}/*`,
                        `arn:aws:s3:::${dlqBucket}/${businessID}/*`,
                    ],
                },
                {
                    Effect: 'Allow',
                    Action: ['s3:ListBucket', 's3:ListBucketMultipartUploads'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`, businessID],
                        },
                    },
                },
            ],
        });
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } = datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        });
    }

    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const platform = dbAccessInformation.platform || SupportedDatastores.s3;
        if (platform.toLowerCase() !== SupportedDatastores.s3) {
            return;
        }

        const { accountId, businessID, measurementId } = dbAccessInformation;
        if (!accountId || !businessID || !measurementId) {
            throw new BadRequestException('accountId, businessID, and measurementId are required for S3 datastore setup');
        }

        const region = dbAccessInformation.region || process.env.AWS_REGION || 'us-east-1';
        const externalId = dbAccessInformation.externalId || randomUUID();
        const roleName = DatastoreAccessInformation.roleName(businessID, measurementId);
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        const ingestion = dbAccessInformation.ingestion || `s3://${ingestionBucket}/${businessID}/`;
        const dlq = dbAccessInformation.dlq || `s3://${dlqBucket}/${businessID}/`;

        const iam = new IAMClient({ region });
        try {
            const createRoleResponse = await iam.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: DatastoreAccessInformation.trustPolicyDocument(accountId, externalId),
                    Description: `Enterprise datastore ingestion role for business ${businessID} measurement ${measurementId}`,
                })
            );

            await iam.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: `${roleName}-s3-access`,
                    PolicyDocument: DatastoreAccessInformation.permissionsPolicyDocument(businessID),
                })
            );

            dbAccessInformation.platform = SupportedDatastores.s3;
            dbAccessInformation.region = region;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = createRoleResponse.Role?.Arn;
            dbAccessInformation.ingestion = ingestion;
            dbAccessInformation.dlq = dlq;
        } catch (e) {
            if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const platform = dbAccessInformation.platform || SupportedDatastores.s3;
        if (platform.toLowerCase() !== SupportedDatastores.s3) {
            return;
        }

        const { accountId, businessID, measurementId, externalId, iamRoleArn } = dbAccessInformation;
        if (!accountId || !businessID || !measurementId || !externalId) {
            throw new BadRequestException(
                'accountId, businessID, measurementId, and externalId are required to update datastore access'
            );
        }

        const region = dbAccessInformation.region || process.env.AWS_REGION || 'us-east-1';
        const roleName = DatastoreAccessInformation.roleName(businessID, measurementId);
        const iam = new IAMClient({ region });

        await iam.send(
            new UpdateAssumeRolePolicyCommand({
                RoleName: roleName,
                PolicyDocument: DatastoreAccessInformation.trustPolicyDocument(accountId, externalId),
            })
        );

        dbAccessInformation.platform = SupportedDatastores.s3;
        dbAccessInformation.region = region;
        dbAccessInformation.externalId = externalId;
        if (iamRoleArn) {
            dbAccessInformation.iamRoleArn = iamRoleArn;
        }
        if (!dbAccessInformation.ingestion) {
            dbAccessInformation.ingestion = `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/`;
        }
        if (!dbAccessInformation.dlq) {
            dbAccessInformation.dlq = `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/`;
        }
    }
}

